function nextBeautifulNumber(n) {
  const isBalanced = (x) => {
    const count = new Array(10).fill(0);
    while (x > 0) {
      count[x % 10]++;
      x = Math.floor(x / 10);
    }
    for (let digit = 0; digit < 10; digit++) {
      if (count[digit] > 0 && count[digit] !== digit) {
        return false;
      }
    }
    return true;
  };
  let candidate = n + 1;
  while (!isBalanced(candidate)) {
    candidate++;
  }
  return candidate;
}

