function nextBeautifulNumber(n) {
  // Build every balanced number with at most 7 digits from its digit multiset, then pick the first above n.
  const all = new Set();
  for (let subset = 1; subset < 1 << 7; subset++) {
    const digits = [];
    for (let d = 1; d <= 7; d++) if (subset & (1 << (d - 1))) for (let k = 0; k < d; k++) digits.push(d);
    if (digits.length > 7) continue;
    const permute = (prefix, rest) => {
      if (!rest.length) { all.add(Number(prefix)); return; }
      for (let i = 0; i < rest.length; i++) {
        if (i > 0 && rest[i] === rest[i - 1]) continue;
        permute(prefix + rest[i], rest.slice(0, i).concat(rest.slice(i + 1)));
      }
    };
    permute('', digits);
  }
  return Math.min(...[...all].filter(x => x > n));
}

