function generate(rand, size) {
  if (size === 'large') return [rand() < 0.5 ? 600000 + Math.floor(rand() * 400001) : Math.floor(rand() * 1000001)];
  const pick = rand();
  if (pick < 0.4) return [Math.floor(rand() * 400)];
  if (pick < 0.7) return [Math.floor(rand() * 50000)];
  return [Math.floor(rand() * 1000001)];
}
